css:
:root{--ink:#233342;--muted:#596877;--accent:#265976;--warm:#ad472d;--line:#d6dcd9;--paper:#fcfbf8;--soft:#edf2f1}
body{background:var(--paper);color:var(--ink);font-family:"Microsoft YaHei",system-ui,sans-serif;font-size:16px;line-height:1.95}
.paper-reading{max-width:1120px;margin:auto;padding:40px clamp(18px,5vw,58px) 80px;overflow-wrap:anywhere}
.paper-reading h1{font:normal clamp(32px,5vw,58px)/1.12 Georgia,"Noto Serif SC",serif;letter-spacing:-.025em;margin:18px 0 26px;text-wrap:balance}
.paper-reading h2{font-size:clamp(25px,3.5vw,34px);font-weight:500;line-height:1.4;margin:0 0 20px;text-wrap:balance}
.paper-reading h3{font-size:20px;font-weight:500;line-height:1.5}.paper-reading p{margin:12px 0 18px}
.paper-hero{padding:16px 0 38px;border-bottom:1px solid var(--line)}
.paper-hero .paper-thesis{font-size:18px;line-height:1.95;max-width:55ch}.paper-hero nav{display:flex;flex-wrap:wrap;gap:8px 22px;margin:26px 0 0}
.paper-hero nav a{font-size:13px;color:var(--accent);text-decoration:underline;text-underline-offset:6px}
.paper-chapter{padding:48px 0 34px;border-bottom:1px solid var(--line);min-width:0}
.paper-chapter :where(section,article,div,figure,fieldset){min-width:0}
.paper-chapter :where(table){display:block;max-width:100%;overflow:auto}
.paper-chapter :where(pre){white-space:pre-wrap;overflow-wrap:anywhere}
.paper-reading button{border:1px solid var(--line);background:transparent;color:var(--accent);padding:8px 14px;min-height:38px;border-radius:4px;font-size:13px;line-height:1.5}
.paper-reading button:hover{background:var(--soft)}.paper-reading button:disabled{opacity:.5;cursor:default}
.paper-reading input[type=range]{accent-color:var(--accent);max-width:100%;min-width:0}.paper-reading input[type=number]{width:90px}
.paper-reading select,.paper-reading input[type=number]{padding:7px 9px;border:1px solid var(--line);background:var(--paper);color:var(--ink);font-size:14px;border-radius:4px;max-width:100%}
.paper-reading input[type=checkbox]{accent-color:var(--warm)}.paper-reading label{font-size:14px;line-height:1.7}
.paper-reading svg,.paper-reading canvas{display:block;max-width:100%;height:auto}
.paper-reading details{padding:14px 0;border-top:1px solid var(--line);margin-top:20px}.paper-reading summary{cursor:pointer;color:var(--accent);font-size:14px}
.paper-reading table{width:100%;border-collapse:collapse;font-size:13px;font-variant-numeric:tabular-nums}
.paper-reading th,.paper-reading td{padding:9px 7px;text-align:left;border-bottom:1px solid var(--line)}
.paper-reading button[data-source]{font-size:12px;color:var(--accent);border:0;padding:6px 0;margin-right:16px;text-decoration:underline;text-underline-offset:4px}
.paper-reading ::selection{background:#f3d5ac;color:#233342}.paper-reading :focus-visible{outline:2px solid var(--accent);outline-offset:4px}
.paper-reading .reading-limitations{font-size:14px;color:var(--muted);padding-top:28px}.paper-reading .reading-limitations h2{font-size:24px}
@media(max-width:480px){.paper-reading{padding-top:24px}.paper-chapter{padding-top:32px}.paper-hero .paper-thesis{font-size:16px}.paper-reading{font-size:15px}.paper-reading h2{font-size:25px}.paper-reading table{font-size:12px}}

@scope (#chapter-problem-gap){.pg-chapter {
  --ink: var(--ink, #1a1a1a);
  --muted: var(--muted, #666);
  --accent: var(--accent, #003366);
  --warm: var(--warm, #cc0066);
  --line: var(--line, #ddd);
  --paper: var(--paper, #f5f5f5);

  font-family: system-ui, sans-serif;
  background-color: var(--paper);
  color: var(--ink);
  padding: 2rem 1rem;
  line-height: 1.6;
  box-sizing: border-box;
}

.pg-chapter * {
  box-sizing: border-box;
}

.pg-header {
  margin-bottom: 2rem;
  border-bottom: 1px solid var(--line);
  padding-bottom: 1rem;
}

.pg-title {
  font-size: 24px;
  font-weight: 700;
  margin: 0 0 0.5rem 0;
  color: var(--accent);
}

.pg-lead {
  font-size: 16px;
  color: var(--muted);
  margin: 0;
  font-family: serif;
}

.pg-interactive-stage {
  background: #fff;
  border: 1px solid var(--line);
  padding: 1.5rem;
  margin: 1.5rem 0;
  border-radius: 4px;
}

.pg-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
  margin-bottom: 1.5rem;
}

.pg-control-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  min-width: 200px;
}

.pg-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
}

.pg-slider {
  width: 100%;
  accent-color: var(--accent);
}

.pg-scale-display {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
  font-family: monospace;
  color: var(--muted);
}

.pg-scale-value.pg-new {
  color: var(--accent);
  font-weight: 700;
}

.pg-toggle {
  padding: 0.5rem 1rem;
  background: #fff;
  border: 1px solid var(--line);
  color: var(--ink);
  font-size: 13px;
  cursor: pointer;
  border-radius: 4px;
}

.pg-toggle[data-state="computational"] {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.pg-tech-status {
  font-size: 12px;
  color: var(--muted);
}

.pg-visualization {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

@media (max-width: 600px) {
  .pg-visualization {
    grid-template-columns: 1fr;
  }
}

.pg-comparison-card {
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: #fafafa;
}

.pg-comparison-card.pg-new-state {
  border-color: var(--accent);
  background: #f0f4f8;
}

.pg-card-title {
  font-size: 15px;
  margin: 0 0 1rem 0;
  color: var(--ink);
}

.pg-features {
  list-style: none;
  padding: 0;
  margin: 0 0 1rem 0;
  font-size: 14px;
}

.pg-features li {
  margin-bottom: 0.5rem;
  padding-left: 1rem;
  position: relative;
}

.pg-features li::before {
  content: "•";
  position: absolute;
  left: 0;
  color: var(--muted);
}

.pg-btn-source {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  font-size: 12px;
  padding: 0.25rem 0.5rem;
  cursor: pointer;
  border-radius: 4px;
}

.pg-btn-source:hover {
  border-color: var(--ink);
  color: var(--ink);
}

.pg-acceptance-feedback {
  padding: 1rem;
  background: #fff;
  border: 1px solid var(--line);
  text-align: center;
  font-size: 14px;
  border-radius: 4px;
}

.pg-acceptance-feedback.active {
  border-color: var(--accent);
  background: #eef4ff;
  color: var(--accent);
  font-weight: 600;
}

.pg-argument-flow {
  margin-top: 2rem;
}

.pg-subtitle {
  font-size: 18px;
  margin: 0 0 1rem 0;
  color: var(--ink);
}

.pg-argument-item {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  margin-bottom: 1rem;
  font-size: 15px;
}

.pg-argument-icon {
  font-weight: 700;
  color: var(--accent);
  min-width: 24px;
}

.pg-argument-text {
  margin: 0;
  flex: 1;
}

.pg-btn-concept {
  background: transparent;
  border: 1px dashed var(--accent);
  color: var(--accent);
  font-size: 12px;
  padding: 0.25rem 0.5rem;
  cursor: pointer;
  border-radius: 4px;
  margin-left: 0.5rem;
}
button[data-source]{background:#fff!important;color:#265976!important}
.katex{display:inline-block;max-width:100%;overflow-x:auto;vertical-align:middle}.step-controls,.control-buttons{flex-wrap:wrap} @media(max-width:480px){.metric-card,.stat-card{min-width:0}}}
@scope (#chapter-data-construction){.chapter-scope {
  --ink: #2c3e50;
  --muted: #7f8c8d;
  --accent: #2980b9;
  --warm: #e74c3c;
  --paper: #ecf0f1;
  --line: #bdc3c7;

  font-family: 'Georgia', 'Times New Roman', serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--ink);
  background-color: var(--paper);
  padding: 2rem;
  border: 1px solid var(--line);
  box-sizing: border-box;
  max-width: 100%;
}

.chapter-scope * {
  box-sizing: border-box;
}

.chapter-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 2rem;
  border-bottom: 2px solid var(--ink);
  padding-bottom: 1rem;
}

.chapter-title {
  font-size: 1.5rem;
  margin: 0;
  font-weight: bold;
  color: var(--ink);
}

.source-btn {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  padding: 0.25rem 0.75rem;
  font-size: 0.85rem;
  cursor: pointer;
  font-family: monospace;
  transition: all 0.2s;
}

.source-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.dataset-workbench {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
  justify-content: center;
  align-items: stretch;
  margin: 2rem 0;
  position: relative;
}

.dataset-pool {
  flex: 1;
  min-width: 280px;
  background: #fff;
  border: 1px solid var(--line);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  transition: transform 0.4s ease, box-shadow 0.4s ease;
  position: relative;
}

.bb-pool {
  border-top: 4px solid var(--accent);
}

.msd-pool {
  border-top: 4px solid var(--muted);
}

.pool-label {
  font-size: 1.2rem;
  font-weight: bold;
  margin-bottom: 0.5rem;
  font-family: monospace;
}

.pool-meta {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.meta-tag {
  background: var(--paper);
  padding: 0.2rem 0.5rem;
  font-size: 0.8rem;
  border: 1px solid var(--line);
  color: var(--muted);
}

.pool-count {
  font-size: 2rem;
  font-weight: bold;
  color: var(--ink);
  margin: 1rem 0;
}

.pool-detail {
  font-size: 0.9rem;
  color: var(--muted);
}

.interaction-core {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 200px;
  gap: 1rem;
}

.overlap-visual {
  width: 100px;
  height: 100px;
  position: relative;
  margin: 1rem 0;
}

.overlap-zone {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  border: 2px dashed var(--warm);
  background: rgba(231, 76, 60, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.5s ease;
}

.overlap-text {
  font-size: 0.7rem;
  color: var(--warm);
  font-weight: bold;
  opacity: 1;
  transition: opacity 0.3s;
}

.action-btn {
  background: var(--ink);
  color: #fff;
  border: none;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  cursor: pointer;
  font-family: monospace;
  transition: background 0.2s;
}

.action-btn:hover {
  background: var(--accent);
}

.action-btn:disabled {
  background: var(--muted);
  cursor: not-allowed;
}

.status-message {
  font-size: 0.9rem;
  color: var(--warm);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  opacity: 1;
  transition: opacity 0.3s;
}

.status-message.success {
  color: var(--accent);
  opacity: 0;
  position: absolute;
  pointer-events: none;
}

.status-icon {
  font-size: 1.2rem;
}

.evidence-note {
  margin-top: 2rem;
  padding: 1rem;
  background: #fff;
  border-left: 4px solid var(--muted);
  font-size: 0.9rem;
  color: var(--muted);
}

.evidence-note p {
  margin: 0.5rem 0;
}

/* State: Cleaned */
.chapter-scope.is-cleaned .overlap-zone {
  border-color: var(--accent);
  background: rgba(41, 128, 185, 0.1);
  transform: scale(0.8);
}

.chapter-scope.is-cleaned .overlap-text {
  opacity: 0;
}

.chapter-scope.is-cleaned #data-construction--status-message {
  opacity: 0;
  display: none;
}

.chapter-scope.is-cleaned #data-construction--status-success {
  opacity: 1;
  position: relative;
  pointer-events: auto;
}

.chapter-scope.is-cleaned #data-construction--pool-bb {
  transform: translateX(-10px);
  box-shadow: -5px 5px 15px rgba(0,0,0,0.05);
}

.chapter-scope.is-cleaned #data-construction--pool-msd {
  transform: translateX(10px);
  box-shadow: 5px 5px 15px rgba(0,0,0,0.05);
}

@media (max-width: 600px) {
  .dataset-workbench {
    flex-direction: column;
  }
  .interaction-core {
    order: -1;
    margin-bottom: 1rem;
  }
  .chapter-scope.is-cleaned #data-construction--pool-bb,
  .chapter-scope.is-cleaned #data-construction--pool-msd {
    transform: none;
  }
}
button[data-source]{background:#fff!important;color:#265976!important}
.katex{display:inline-block;max-width:100%;overflow-x:auto;vertical-align:middle}.step-controls,.control-buttons{flex-wrap:wrap} @media(max-width:480px){.metric-card,.stat-card{min-width:0}}
.dataset-pool,.interaction-core{min-width:0;max-width:100%}}
@scope (#chapter-style-vocab-trend){:scope .chapter-container {
  font-family: var(--font-serif, serif);
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  line-height: 1.6;
}

:scope .chapter-header h1 {
  font-size: 1.8rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
  border-bottom: 2px solid var(--accent);
  display: inline-block;
}

:scope .meta-info {
  display: flex;
  gap: 1rem;
  margin-bottom: 2rem;
}

:scope .badge {
  background: var(--muted);
  color: var(--paper);
  padding: 0.2rem 0.6rem;
  border-radius: 4px;
  font-size: 0.85rem;
  font-family: var(--font-sans, sans-serif);
}

:scope .content-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 2rem;
}

@media (max-width: 768px) {
  :scope .content-grid {
    grid-template-columns: 1fr;
  }
}

:scope .viz-card {
  background: #f8f9fa;
  border: 1px solid var(--line);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  border-radius: 6px;
}

:scope .viz-card h3 {
  font-family: var(--font-sans, sans-serif);
  font-size: 1.1rem;
  margin-top: 0;
  color: var(--accent);
}

:scope .year-toggle {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

:scope .year-toggle button {
  background: transparent;
  border: 1px solid var(--line);
  padding: 0.4rem 1rem;
  cursor: pointer;
  font-family: var(--font-sans, sans-serif);
  color: var(--muted);
}

:scope .year-toggle button.active,
:scope .year-toggle button[aria-pressed="true"] {
  background: var(--accent);
  color: var(--paper);
  border-color: var(--accent);
}

:scope .cloud-container {
  min-height: 200px;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-content: flex-start;
  font-family: var(--font-sans, sans-serif);
}

:scope .cloud-word {
  padding: 0.2rem 0.5rem;
  background: #e9ecef;
  border-radius: 3px;
  font-size: 0.9rem;
  transition: transform 0.2s;
}

:scope .cloud-word:hover {
  transform: scale(1.1);
  background: var(--accent);
  color: var(--paper);
}

:scope .cloud-word.highlight {
  background: var(--warm);
  color: var(--paper);
  font-weight: bold;
}

:scope .chart-wrapper {
  width: 100%;
  height: 200px;
  margin-bottom: 1rem;
}

:scope .legend {
  display: flex;
  gap: 1rem;
  font-size: 0.85rem;
  font-family: var(--font-sans, sans-serif);
  color: var(--muted);
}

:scope .legend-item {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

:scope .dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

:scope .dot.bb { background: var(--accent); }
:scope .dot.msd { background: var(--muted); }

:scope .analysis-panel {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

:scope .argument-block {
  background: var(--paper);
  padding: 1rem;
  border-left: 3px solid var(--line);
}

:scope .warning-block {
  border-left-color: var(--warm);
  background: #fff5f5;
}

:scope .limitation-text {
  font-size: 0.9rem;
  color: #d63030;
  font-style: italic;
}

:scope .source-bar {
  margin-top: 1rem;
  display: flex;
  gap: 0.5rem;
  border-top: 1px solid var(--line);
  padding-top: 0.5rem;
}

:scope button.source-btn,
:scope button.concept-btn,
:scope button.ask-btn {
  font-size: 0.8rem;
  padding: 0.3rem 0.6rem;
  border: 1px solid var(--line);
  background: transparent;
  cursor: pointer;
  font-family: var(--font-sans, sans-serif);
  color: var(--ink);
}

:scope button.source-btn:hover {
  background: var(--muted);
  color: var(--paper);
}

:scope .mini-viz {
  margin-top: 0.5rem;
  padding: 0.5rem;
  background: #f1f3f5;
  border-radius: 4px;
}

:scope .track {
  display: flex;
  align-items: flex-end;
  height: 40px;
  gap: 1rem;
}

:scope .bar {
  width: 60px;
  text-align: center;
  color: var(--paper);
  font-size: 0.8rem;
  font-family: var(--font-sans, sans-serif);
  padding-top: 4px;
}

:scope .bar.rock {
  height: 80%;
  background: var(--accent);
}

:scope .bar.blues {
  height: 40%;
  background: var(--muted);
}

:scope .caption {
  display: block;
  font-size: 0.75rem;
  color: var(--muted);
  margin-top: 4px;
  text-align: center;
}

                .axis-line { stroke: var(--line); stroke-width: 1; }
                .grid-line { stroke: var(--line); stroke-width: 0.5; stroke-dasharray: 4; }
                .bb-line { stroke: var(--accent); stroke-width: 2; fill: none; }
                .msd-line { stroke: var(--muted); stroke-width: 2; stroke-dasharray: 4; fill: none; }
                .point { fill: var(--paper); stroke: var(--accent); stroke-width: 1.5; }
                .label { font-size: 10px; fill: var(--ink); font-family: monospace; }
                .axis-label { font-size: 12px; fill: var(--muted); font-family: sans-serif; }

button[data-source]{background:#fff!important;color:#265976!important}
.katex{display:inline-block;max-width:100%;overflow-x:auto;vertical-align:middle}.step-controls,.control-buttons{flex-wrap:wrap} @media(max-width:480px){.metric-card,.stat-card{min-width:0}}}
@scope (#chapter-style-structural-metrics){.pm-chapter-style-structural-metrics {
  --pm-ink: var(--ink, #1a1a1a);
  --pm-muted: var(--muted, #666);
  --pm-accent: var(--accent, #003366);
  --pm-warm: var(--warm, #cc0066);
  --pm-line: var(--line, #ddd);
  --pm-paper: var(--paper, #f5f5f5);

  font-family: serif;
  background-color: var(--pm-paper);
  color: var(--pm-ink);
  padding: 2rem 1rem;
  border: 1px solid var(--pm-line);
  margin: 1rem 0;
  box-sizing: border-box;
}

.pm-chapter-style-structural-metrics * {
  box-sizing: border-box;
}

.pm-header h2 {
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
  color: var(--pm-accent);
  font-weight: 600;
}

.pm-lead {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--pm-muted);
  margin-bottom: 2rem;
  max-width: 800px;
}

.pm-interaction-container {
  display: flex;
  flex-direction: column;
  gap: 2rem;
  max-width: 800px;
}

.pm-control-panel {
  background: #fff;
  padding: 1.5rem;
  border: 1px solid var(--pm-line);
  position: relative;
}

.pm-label {
  display: block;
  font-family: monospace;
  font-size: 0.9rem;
  margin-bottom: 1rem;
  color: var(--pm-ink);
}

.pm-value {
  font-weight: bold;
  color: var(--pm-accent);
}

input[type="range"] {
  width: 100%;
  accent-color: var(--pm-accent);
  cursor: pointer;
}

.pm-thresholds {
  position: relative;
  height: 1.5rem;
  margin-top: 0.5rem;
  border-top: 1px solid var(--pm-line);
}

.pm-mark {
  position: absolute;
  transform: translateX(-50%);
  font-size: 0.75rem;
  color: var(--pm-muted);
  font-family: monospace;
  top: 100%;
  padding-top: 0.25rem;
}

.pm-metrics-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
}

.pm-metric-card {
  background: #fff;
  padding: 1rem;
